### Reproduction

https://stackblitz.com/edit/github-omszpj?file=modules%2Fmy-module%2Findex.ts,plugins%2FmyPlugin.ts

### Describe the bug

- `module.ts`

```ts
export default defineNuxtModule({
  meta: {
    name: 'myModule',
    configKey: 'myModule',
    compatibility: {
      nuxt: '^3.0.0',
    },
  },
  defaults: {
    myConfig: {
      name: 'Test',
      val1: null,
      val2: undefined,
      val3: 0,
      val4: '',
    },
  },
  async setup(moduleOptions, nuxt) {
    nuxt.options.runtimeConfig.public.myModule = defu(
      nuxt.options.runtimeConfig.public.myModule as any,
      { ...moduleOptions }
    );

    console.log('Module Setup:', nuxt.options.runtimeConfig.public.myModule); 
    // => Module Setup: { myConfig: { name: 'Test', val1: null, val2: undefined, val3: 0, val4: '' } }
  },
});
```

- `plugin.ts`

```ts
export default defineNuxtPlugin(() => {
  const {
    public: { myModule },
  } = useRuntimeConfig();

  console.log('Plugin:', myModule);
  // => Plugin: { myConfig: { name: 'Test', val1: '', val2: '', val3: 0, val4: '' } }
});
```

